osition:absolute;top:50%;right:14px;transform:translateY(-50%);color:var(--gray-600);pointer-events:none}.field textarea{min-height:110px;resize:vertical}.char-count{position:absolute;right:14px;bottom:10px;padding-left:4px;background:#fff;color:var(--gray-400);font-size:12px}.upload-zone{padding:36px 20px;border:1.5px dashed var(--gray-300);border-radius:10px;text-align:center;cursor:pointer;transition:border-color .15s,background .15s}.upload-zone:hover,.upload-zone.dragover{border-color:var(--blue-700);background:#f8fafc}.upload-zone svg{margin-bottom:10px;color:var(--gray-500)}.upload-title{margin-bottom:4px;color:var(--gray-600);font-size:14px}.upload-sub{color:var(--gray-400);font-size:12px}.upload-zone input{display:none}.file-list{margin-top:10px;color:var(--gray-600);font-size:13px;text-align:left}.file-list div{padding:4px 0}.form-footer{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px;margin-top:8px}.checkbox-field{display:flex;align-items:center;gap:8px;color:var(--gray-800);font-size:14px}.checkbox-field input{width:18px;height:18px;accent-color:var(--blue-700)}.btn-submit{padding:12px 28px;border:0;border-radius:8px;background:var(--blue-900);color:#fff;font-size:14px;font-weight:600;cursor:pointer}.btn-submit:hover{background:var(--blue-800)}.error-message{margin-bottom:20px;padding:12px 14px;border:1px solid #fecaca;border-radius:8px;background:#fef2f2;color:#b91c1c;font-size:13px}.field-error{margin-top:6px;color:#b91c1c;font-size:12px}.success-message{margin-bottom:20px;padding:12px 14px;border:1px solid #a7f3d0;border-radius:8px;background:#ecfdf5;color:#047857;font-size:13px}@media(max-width:768px){.nav-links{display:none}.nav-links.is-open{display:flex;position:absolute;top:64px;left:0;right:0;z-index:50;flex-direction:column;align-items:flex-start;gap:16px;padding:16px 24px;border-bottom:1px solid var(--gray-100);background:#fff}.form-card{padding:22px 18px}.form-footer{align-items:stretch;flex-direction:column}.btn-submit{width:100%}}
