<script>const menuButton=document.getElementById('menuBtn'),links=document.querySelector('.nav-links');menuButton.addEventListener('click',()=>{const open=links.classList.toggle('is-open');menuButton.setAttribute('aria-expanded',open)});const zone=document.getElementById('uploadZone'),input=document.getElementById('fileInput'),list=document.getElementById('fileList');zone.addEventListener('click',e=>{if(e.target!==input)input.click()});input.addEventListener('change',()=>renderFiles(input.files));['dragenter','dragover'].forEach(event=>zone.addEventListener(event,e=>{e.preventDefault();zone.classList.add('dragover')}));['dragleave','drop'].forEach(event=>zone.addEventListener(event,e=>{e.preventDefault();zone.classList.remove('dragover')}));zone.addEventListener('drop',e=>{input.files=e.dataTransfer.files;renderFiles(input.files)});function renderFiles(files){list.innerHTML=Array.from(files).map(file=>`<div>📎 ${file.name}</div>`).join('')}const description=document.getElementById('deskripsi');description.addEventListener('input',()=>document.getElementById('charCount').textContent=`${description.value.length}/500`);</script>
